func (e ListTorrentsParamsSort) Valid() bool {
	switch e {
	case CompletedDesc:
		return true
	case PublishedAsc:
		return true
	case PublishedDesc:
		return true
	case SizeAsc:
		return true
	case SizeDesc:
		return true
	default:
		return false
	}
}

